properties.source_statement_tex:
There are proof builders, for $y:L$ and $t:B(A)$, of
\begin{equation}
 \langle\operatorname{Round}(y),t\rangle_L
       \leftrightarrow\langle y,t\rangle_L.
\label{chan-primitive-round}
\end{equation}
For every formula $\Phi$ under $x:L$ and every $w:L$, there is a proof of
\begin{equation}
 \operatorname{pred}(x.\Phi)@w
       \leftrightarrow\Phi[x:=\operatorname{Round}(w)].
\label{chan-predicate-evaluation}
\end{equation}

Under $A:s$, $m:M(A)$, $y:L(A)$ and the proof input $d_m:\neg D(m)$,
there is a proof of
\begin{equation}
 \operatorname{Access}(\operatorname{Bundle}(m,y);o,x.\Psi)
        \leftrightarrow\Psi(m,\operatorname{Round}(y)).
\label{chan-access-law}
\end{equation}
The definitions of $\operatorname{Bundle}$ and $\operatorname{Access}$
themselves do not use $d_m$.

A sorted normal expression is a sort, a neutral expression, or a
product. Its profile is determined as follows:
\begin{enumerate}
\item a literal sort $s$ has profile $\operatorname{Ax}(s)$;
\item a neutral expression has a singleton profile $\{s\}$, and
      $\operatorname{Ax}(s)$ is nonempty;
\item a normal product $\Pi x:D.E$ has profile
\[
 \operatorname{Out}\bigl(\pi_\Gamma(D),
                         \pi_{\Gamma,x:D}(E)\bigr).
\]
\end{enumerate}
Profiles are unchanged by valid thinning and context conversion.
If $\xi:\Gamma\to\Delta$ is a typed substitution, then
\begin{equation}
                  \pi_\Gamma(T)
                    \subseteq\pi_\Delta(T\xi).
\label{eq:profile-growth}
\end{equation}

The inclusion-ordered set $\mathcal C(T)$ is a complete lattice with
largest element $\top_T$. Write $\bot_T$ for its least element.
For an actual product $T=\Pi x:D.E$, choose a set
$A\subseteq\top_D$. For each $n\in A$ choose any family of candidates
$C_{n,a}\in\mathcal C(T_n)$ indexed by a set $Q_n$. Then
\begin{equation}
 \{h\in\top_T:\text{for every }n\in A\text{ and }a\in Q_n,
                                  \ h n\in C_{n,a}\}
\label{eq:product-test-candidate}
\end{equation}
is a candidate at $T$.

Assume \eqref{eq:processed-invariant} and an implementation of
the three interface requirements in Section~\ref{subsec:candidate-interface}
for $S$. If $\Gamma\vdash M:A$, the expression $M$ is strongly
normalizing, and $(\xi,\theta)$ is admissible, then
\begin{equation}
                         M\xi\in R_{\Gamma,A^\#}(\xi,\theta).
\label{eq:sn-fundamental}
\end{equation}

Under \(h:\operatorname{Resp}(v)\), let
\(P_x=\operatorname{Pair}(\operatorname{Part}(v),x^0)\).
For every \(x':X\) there are proofs
\begin{align}
 P_x@(x'^{\,\ell})&\leftrightarrow
                         v\diamond_m(x'^{\,0}), \label{rel-pair-left}\\
 P_x@(x'^{\,r})&\leftrightarrow x\simeq x'. \label{rel-pair-right}
\end{align}

Define, without proof hypotheses,
\[
 \operatorname{WF}=\operatorname{mk}_X(v.\,\operatorname{Ind}(i_v)):X.
\]
There is a proof $V_{\operatorname{WF}}:
\operatorname{Valid}(\operatorname{WF})$.  For
$ex:\operatorname{Ext}(i)$ there is a builder
\begin{equation}
 w_{ex}:\operatorname{le}(i,\operatorname{WF})
                       \leftrightarrow\operatorname{Ind}(Si).
 \label{rel-wf-evaluation}
\end{equation}
Finally, from $i:\mathsf P_X$, $ex:\operatorname{Ext}(i)$ and
$l:\operatorname{Ind}(i)$ there is a builder
\begin{equation}
 b(i,ex,l):i@\operatorname{WF}.
 \label{rel-induction-builder}
\end{equation}

At every child edge, \(b'\) is an actual triple in \(W\), while
\(a'\) is either \(a\) or an actual triple of \(E\). On its child,
\begin{equation}
 W'\cap S\subseteq D_{a'}\cap P_b,
 \qquad
 W'\setminus S\subseteq P_{b'}.
 \label{eq:edge-labels}
\end{equation}
Every child excludes the center and is strictly smaller than its parent.
The root has no nonempty switched child.

For a global upset list \(\K=(K_1,\ldots,K_\ell)\), fix
\(1\le d\le\ell\) and an integer \(0\le r\le N+1\), and form
\begin{equation}
 \operatorname{carry}_{d,r}(\K)
 =\bigl(K_d\cap\{\rk\ge r\},K_{d+1},\ldots,K_\ell\bigr).
 \label{eq:carry}
\end{equation}
Its qualifier set consists exactly of the old global qualifiers with
old key at least \((d,r)\). Among those jobs the new list preserves
the old key order. Its entries are global upsets.

\label{filt:initial}
With $A,V,E,W$ and $\prec$ as above, for every $d\in\Z$, every
$p\geq0$, and every $j\in\Z$ one has
\begin{align}
 \dim_F(E/W)_d
    &=\dim_F(E/\operatorname{in}_{\prec}W)_d,
       \label{filt:hilbert}\\
 \beta^A_{p,j}(E/W)
    &\leq\beta^A_{p,j}(E/\operatorname{in}_{\prec}W).
       \label{filt:betti}
\end{align}

Let \(r\ge1\), let \(b_1,\ldots,b_r\) be positive integers, and let
\(d\in\Z\).  If \(X\subseteq\mathcal B_r(d)\) is stable and
\(Y=\operatorname{Lex}(X)\), then \(\partial Y\) is a lex segment and
\begin{equation}
 \label{box:three-inequalities}
 |\partial X|\ge|\partial Y|,
 \qquad |X(0)|\ge|Y(0)|,
 \qquad |X(b_r)|\le|Y(b_r)|.
\end{equation}

In the coordinates \eqref{eq:groupoid-coordinates}, the $D$-linear
extension of integration $\epsilon_Y:A_Y\to\one$ is the map
\begin{equation}\label{eq:absolute-weights}
 (x_\alpha)_{[\alpha]}\longmapsto
       \sum_{[\alpha]}\frac{x_\alpha}{a_\alpha}.
\end{equation}
For a map $f:Y\to Z$, its pushforward has coordinate formula
\begin{equation}\label{eq:relative-weights}
 \bigl(f_!(x)\bigr)_\beta
   =\sum_{[\alpha]:[f\alpha]=[\beta]}
       \frac{a_\beta}{a_\alpha}\,x_\alpha.
\end{equation}
Consequently $\chi_\beta(f_!1)$ is the rational scalar
\begin{equation}\label{eq:relative-fiber-mass}
 \left|
   \mathcal X_\Gamma(Y)
       \mathop{\times}^{h}_{\mathcal X_\Gamma(Z)}\{\beta\}
 \right|_{\mathrm h}
\end{equation}
times the unit of $D$.

For every finite group $F$,
\begin{equation}\label{eq:hom-integrality}
 \frac{|\Hom_{\cts}(\Gamma,F)|}{|F|}\in\Z_{(p)}.
\end{equation}

For every open subgroup $U\le_o\Gamma$, every finite continuous $U$-set
$X$, and every $h\geq0$,
\begin{equation}\label{eq:subgroup-congruence}
 \sum_{\substack{V\le_o U\\{}[U:V]=p^h}}
       \bigl(|X^V|-|X|\bigr)
       \in p^{h+1}\Z_{(p)}.
\end{equation}
The sum is over all open subgroups of the indicated index.

For $d\geq1$, let $a_j(d)$ be the number of open subgroups of index
$p^j$ in $\Z_p^d$.  Then
\begin{equation}\label{eq:lattice-generating-function}
 \begin{aligned}
 \sum_{j\geq0}a_j(d)t^j
       &=\prod_{u=0}^{d-1}(1-p^u t)^{-1},\\
 \lim_{j\to\infty}a_j(d)
       &=c_d:=\prod_{u=1}^{d-1}(1-p^u)^{-1}\ne0
 \quad\text{in }\Z_p.
 \end{aligned}
\end{equation}

For a finite \(p\)-group \(P\) and integers \(k,l\ge0\),
\begin{equation}\label{eq:height-gluing}
 T(k)\wedge U_P(L_{T(l)}S)\ne0
 \quad\Longrightarrow\quad k+\ell(P,1)\le l.
\end{equation}

For every finite \(p\)-group \(P\) and all \(m,k\ge0\),
\begin{equation}\label{eq:finite-gluing}
 m<k+\ell(P,1)\quad\Longrightarrow\quad
 T(k)\wedge U_P(L_m^fS)=0.
\end{equation}

The increments $\Delta_N^{L,\mathbf u}=P_{N+1}^{L,\mathbf u}-P_N^{L,\mathbf u}$
are uniformly bounded in $N,L,\mathbf u$. There is a reservoir on $N$ spins
with physical interaction count of mean
\begin{equation}\label{cavity:reservoir-mean}
 \rho_N=\alpha(N+1)\left(\frac{N}{N+1}\right)^p,
\end{equation}
the usual fields, and the perturbation counts of means $c_\nu s_N$, such that
\begin{equation}\label{cavity:identity}
 \Delta_N^{L,\mathbf u}
 =\log2+\E\log Y_{0,\rm s}-\E\log Y_{0,\rm b}+o_N(1).
\end{equation}
The error is uniform in $L,\mathbf u$. The insertion recursion uses the
tilted reservoir kernels and independent new root disorder, with terminal
insertions
\begin{align}
 A_{\rm s}(\sigma)&=\frac12\sum_{\eps=\pm1}
 \exp\left(h\eps+\sum_{j=1}^{K_{\rm s}}
 \theta_j(\sigma_{i_{1,j}},\ldots,\sigma_{i_{p-1,j}},\eps)\right),
 \label{cavity:site-insertion}\\
 A_{\rm b}(\sigma)&=\exp\left(\sum_{j=1}^{K_{\rm b}}
 \theta_j(\sigma_{i_{1,j}},\ldots,\sigma_{i_{p,j}})\right),
 \label{cavity:bond-insertion}
\end{align}
where $K_{\rm s}\sim\Pois(\alpha p)$, $K_{\rm b}\sim\Pois(\alpha(p-1))$,
and all displayed indices are independent uniform indices in $[N]$.

For the trial laws of \cref{comp:encoding}, with
$\mathbf m^{(L)}=(1/L,\ldots,(L-1)/L)$,
\begin{equation}\label{comp:increment-comparison}
 \lim_{L\to\infty}\limsup_{N\to\infty}
 \left|\Delta_N^{L,\mathbf u_{L,N}}
 -\cB_{L-1}(\zeta_{L,N},\mathbf m^{(L)})\right|=0.
\end{equation}

For every fixed labeled topology $S$,
\begin{equation}
 \lim_{L\to\infty}\limsup_{N\to\infty}
       \mathcal A_{L,\eta}\operatorname{Var}(R_S)=0
       \qquad(\eta>0),
 \label{decor:overlap-concentration-equation}
\end{equation}
where only the $b(S)$ branching depths are averaged. For a
singleton, whose average has no coordinates,
$\operatorname{Var}(R_S)\to0$ as $N\to\infty$ at every fixed $L$.

If a random vector $B\in[-1,1]^N$ is conditionally independent of $A_S$
given $\mathscr F_d$, then
\begin{equation}
 \bigl\|(A_S-\mu_{d,S})\cdot B\bigr\|_{L^2}
        \le v_N(S,d)^{1/4}.
 \label{decor:contraction-bound}
\end{equation}
If $X,Y,Z$ are conditionally independent copies of a bounded random
vector given a sigma field $\mathscr G$, and $C$ is its conditional
covariance matrix, then
\begin{equation}
 \mathbb E(X\cdot Y-X\cdot Z)^2
       \ge \frac2{N^2}\mathbb E\sum_{i,j}C_{ij}^2.
 \label{decor:three-copy-bound}
\end{equation}

For every fixed labeled topology $S$ and every $\eta>0$,
\begin{equation}
 \lim_{L\to\infty}\limsup_{N\to\infty}
       \mathcal A_{L,\eta}v_N(S,d)=0,
 \label{decor:conditional-concentration-equation}
\end{equation}
where the average ranges over all branching depths of $S$ and an
additional regular depth $d$ strictly before its first split.  For a
singleton, the average ranges over $d$ alone.

Under \eqref{model:integrability}--\eqref{model:positivity}, the thermodynamic
limit exists and
\begin{equation}\label{main:formula}
 \lim_{N\to\infty}F_N=\inf_{r\ge0}\Phi_r.
\end{equation}

For each fixed $L$ and each fixed type $\nu$,
\begin{equation}
 \int e_{\nu,N}(\mathbf u)\,\pi(d\mathbf u)\longrightarrow0.
 \label{pert:concentration-eq}
\end{equation}
The assertion holds for the reservoir as well as for the original
system.  Constants need not be uniform in $L$ or $\nu$.

For every fixed $L\geq2$ and $\varepsilon>0$, there are sizes
$N_j\uparrow\infty$ and deterministic vectors $\mathbf u_j$ such that
\begin{enumerate}[label=\textup{(\roman*)}]
 \item $\Delta_{N_j}(\mathbf u_j)\leq \underline F+2\varepsilon$;
 \item for every fixed type $\nu$,
 $e_{\nu,N_j}(\mathbf u_j)\longrightarrow0$ in the reservoir;
 \item in the reservoir, the expectations of every finite product of multioverlaps on
 every fixed finite prescribed tree of depth $L$ converge along this
 sequence.
\end{enumerate}

If $\nu$ is a type with the specified marks, then
\begin{equation}
 |H_N(t_\nu,u_\nu)|\leq\|f\|_\infty e_{\nu,N}.
 \label{pert:palm-bound}
\end{equation}
For a fixed mark specification the function $H_N(t,u)$ is the same
for all its types $j$: its base reservoir contains the full original
Poisson families, including all types.

\label{pert:identity}
For the perturbation family defined above, along every sequence from
Lemma~\ref{pert:selection},
\begin{equation}
 \sum_{E\in\mathfrak E(\mathcal T,a_*,\mathcal C)}
       c_E\,\mathbb E[fR_E]
 -\mathbb E f
  \sum_{E\in\mathfrak E(\{a_*\},a_*,\mathcal C)}
       c_E\,\mathbb E[R_E]
 \longrightarrow0.
 \label{pert:tree-identity-eq}
\end{equation}
This holds for every fixed old tree, either kind of anchor, every
bounded polynomial $f$ in its multioverlaps, every finite number of
ordered added colors, and every prescribed constraint $\mathcal C$.
The empty addition is allowed.  The error is taken to zero at fixed
$L$, fixed tree, and fixed constraint, before any limit in $L$.

Couple two interaction laws $\theta,\theta'$ and two field laws $h,h'$,
each satisfying \eqref{model:integrability} for the fixed $p$ and $\alpha$,
and put $D=\E\max_s|\theta(s)-\theta'(s)|$ and
$d=\E|h-h'|$. Then
\begin{align}
 |F_N-F_N'|&\le\alpha D+d,\label{reduction:free-stability}\\
 |\cB_r(\zeta,\mathbf m)-\cB_r'(\zeta,\mathbf m)|
 &\le\alpha(2p-1)D+d\label{reduction:trial-stability}
\end{align}
uniformly in $N,r$ and all trial laws, including $r=0$.
If $c$ is an integrable random constant associated with an interaction and
$\widehat\theta=\theta-c$, then
\begin{equation}\label{reduction:shift}
 \widehat F_N=F_N-\alpha\E c,
 \qquad\widehat{\cB}_r=\cB_r-\alpha\E c.
\end{equation}

For a bounded real path function $D$ and $A=1+tD$,
\begin{equation}\label{tree:log-series}
  \log Y_0
   =\sum_{k\geq1}\frac{(-1)^{k-1}t^k}{k}
       \mathbb E_{Q_k}E_{\mathcal T}
          \prod_{a=1}^k D^a,
       \qquad |t|\|D\|_\infty<1.
\end{equation}
This identity is conditional on the root.  If
$|t|\|D\|_\infty\leq c<1$, the absolute value of the remainder after
order $K$ is at most
\begin{equation}\label{tree:log-tail}
  \sum_{k>K}\frac{c^k}{k}.
\end{equation}

Let $H$ be a bounded function of the variables on the old tree, fixed
as the insertion parameters vary.  For
$A_{\boldsymbol t}=1+\sum_{j=1}^k t_jD_j$, with bounded real path
functions $D_j$, one has
\begin{equation}\label{tree:mixed-expansion}
  \left.\partial_{t_1}\cdots\partial_{t_k}
       E_{\mathcal T}^{A_{\boldsymbol t}}
        \frac{H}{A_{\boldsymbol t}^{a_*}}
  \right|_{\boldsymbol t=0}
   =\sum_E c_E\,
       E_{\mathcal T_E}
          \left[H\prod_{j=1}^kD_j^{a_j(E)}\right].
\end{equation}
The formula holds in any fixed order of the colors.  For identical
directions $D_j=D$, the coefficient of $t^k$ is the right-hand side
divided by $k!$.  The analytic bounds established above apply to its
left-hand side, uniformly over the path kernels.  The empty extension has weight $1$.

For every fixed $k$ there is $C_k<\infty$, independent of $L$ and
$\eta$, such that
\begin{equation}\label{tree:irregular-probability}
  Q_k\{\mathcal T\text{ is not regular}\}
        \leq C_k(\eta+L^{-1}).
\end{equation}
For any particular labeled topology with $a$ branching vertices and
any consistent assignment of their depths,
\begin{equation}\label{tree:assignment-probability}
  Q_k\{\text{that topology and depth assignment}\}
       \leq C_kL^{-a}.
\end{equation}
Deleting leaves from a regular tree produces a regular tree, after
discarding branching vertices that become unary.

For all $\gamma,\nu\in[0,1]$ and every integer $n\ge1$,
\begin{equation}\label{eq:main}
 \chi(\A_{\gamma,\nu}^{\otimes n})
 =n\chi(\A_{\gamma,\nu})
 =\frac n{\ln2}\max_{0\le p\le1}
 \{h((1-\gamma)p+\gamma\nu)-g(v_{\gamma,\nu}(p))\},
\end{equation}
where
\begin{equation}\label{eq:v-main}
 v_{\gamma,\nu}(p)
 =\gamma\nu(1-\nu)+\gamma(1-\gamma)(p-\nu)^2.
\end{equation}
In particular, $C(\A_{\gamma,\nu})=\chi(\A_{\gamma,\nu})$.
If $p$ maximizes \eqref{eq:main}, independent products of the two
equiprobable signals
\begin{equation}\label{eq:pair}
 \phi_\pm=\sqrt{1-p}\,\ket0\ \pm\sqrt p\,\ket1
\end{equation}
attain the Holevo information at every block length.

For each fixed $Z\in\C^{N\times N}$, the function
\begin{equation}\label{eq:block-G}
 G_Z(D,E)=\ln\det(D+ZE^{-1}Z^*)-\ln\det D,
 \qquad D,E>0,
\end{equation}
is jointly convex on pairs of positive definite Hermitian matrices.

Let $X,Y$ be complex matrices of the same rectangular shape with
$\Tr(XX^*)=\Tr(YY^*)=1$. Suppose
$\alpha,\beta,\eta,\delta\ge0$ sum to one and
\begin{equation}\label{eq:thermal-condition}
 \alpha\delta-\beta\eta=K^2,\qquad K\ge0.
\end{equation}
Set
\begin{equation}\label{eq:thermal-state}
 T=\begin{pmatrix}
 \alpha XX^*+\beta YY^*&KXY^*\\
 KYX^*&\eta XX^*+\delta YY^*
 \end{pmatrix},\qquad
 U_0=\alpha+\beta,\quad U_1=\eta+\delta,
\end{equation}
and $u=U_0U_1-K^2$. Then $T$ is a state, $0\le u\le1/4$, and
\begin{equation}\label{eq:thermal-bound}
 \ent(T)\ge(\alpha+\eta)\ent(XX^*)
             +(\beta+\delta)\ent(YY^*)+g(u).
\end{equation}

Let $B_s>0$ and $\lambda>0$. Suppose an alive scalar quantity has an ordinary increment $\Delta$
with $|\mathbb E\Delta|\le\mu$,
$\mathbb E\Delta^2\le\nu$, and $|\Delta|\le\lambda B_s$.
For each fixed even $p\ge2$, the upper-excess account for either
sign, measured in units $\lambda B_s$, has expectation factor at most
\begin{equation}
 1+C_p\left(\frac{\mu}{\lambda B_s}
             +\frac{\nu}{\lambda^2B_s^2}\right).
 \label{eq:original-34}
\end{equation}
The threshold, exceptional-transition, and death conventions are
those of Lemma~\ref{lem:scalar-excess}.

At a current early or cleanup state, assume $l\ge l_0$, the core
bound \eqref{eq:original-3}, and actual girth at least $g_0$.
Assume positivity and \eqref{eq:original-8} at every tracked primary
and auxiliary parameter, for both signs.
For $B_h^+=\mathcal D+h^{-2}\alpha I$, the positive operator
$S_h=(B_h^+)^{1/2}W(B_h^+)^{1/2}$ has norm at most
$n^{v_*}/\alpha$. For a sufficiently large fixed $C$, the sum of its
eigenvalues above $Cn^c/\alpha$ is at most $n^{v_*}/\alpha$.
These bounds hold at the primaries and their auxiliaries. At all these
points, every global coordinate or centered stub $f$ satisfies
\begin{equation}
 f^TW(\mathcal D+h^{-2}\alpha I)Wf
   \le(1+h^{-2})\|f_\perp\|^2+n^{-c_1}.
 \label{eq:original-10}
\end{equation}
At the primaries, the averaged trace identity is
\begin{equation}
 \frac{\operatorname{Tr}K_{\rm all}}l+
       h^{-2}\alpha\frac{\mathcal T}{l}
       =1+h^{-2}+O(n^{-c_2}).
 \label{eq:original-11}
\end{equation}
The following moment bounds hold at both primaries and auxiliaries:
\begin{equation}
 \begin{split}
 \operatorname{Tr}K_{\rm all}^2+
       \alpha^2\operatorname{Tr}Q_{\rm all}^2
   &\le C\left(n^{2c}l/\alpha^2+n^{4v_*}/\alpha^4\right),\\
 \operatorname{Tr}(\Gamma K_{\rm all})+
       \alpha\operatorname{Tr}(\Gamma Q_{\rm all})
   &\le C\left(n^cl/\alpha+n^{3v_*}/\alpha^3\right),\\
 \|Q_{\rm all}\|&\le Cn^{2v_*}/\alpha^3.
 \end{split}
 \label{eq:original-12}
\end{equation}
The decay exponents $c_1,c_2>0$ are fixed independently of $n$.

For every existing output pair, conditionally on its survival,
\begin{equation}
 \big|\mathbb E\Delta E_{ij}\big|\le \mu_l,
 \qquad
 \mu_l=C\left[
 \frac{n^{v_*}/\alpha_*+n^\eta q^{L/2}+D_g}{l^2}
 +\frac{n^\eta}{l^{3/2}}+\frac{d_m^2}{l}\right].
\label{eq:original-22}
\end{equation}
This includes recentered stub outputs.

For any fixed radius \(R_c\), the simultaneous accounts retain
\begin{equation}
\begin{split}
 &T_S=\sum_{x\in S}e_x(x)^2\le n^\eta,
 \qquad T_V=\sum_{i\in V}E_{ii}^2\le n^\eta n/l_0,\\
 &T_{XS,k}=\sum_{\substack{i\in X,\ x\in S\\
    \operatorname{dist}(\operatorname{vtx}i,\operatorname{vtx}x)\le k}}
           e_i(x)^2\le n^\eta,
 \qquad X\in\{V,S\},\quad 0\le k\le R_c .
\end{split}
\label{eq:original-23}
\end{equation}
The final exponent \(\eta>0\) may be prescribed in advance and
made arbitrarily small.

For every surviving output pair, decompose its actual increment as
\(\Delta E_{ij}=B_e\mathcal L_{ij}+\mathcal N_{ij}\), where
\(\mathcal L\) is linear in \(z\) and evaluated on the old output
vectors. The residual contains the nonlinear terms, the formal tail,
and the recentering of surviving stub outputs. It has sup
\[
 |\mathcal N_{ij}|\le C(d_m^2+B_{\rm tail}+d_m/l)
\]
and conditional second moment
\begin{equation}
 \mathbb E|\mathcal N_{ij}|^2
 \le C(n^\eta/l^2+d_m^4/l).
\label{eq:original-29}
\end{equation}
The leading terms of \(\mathcal L_{ij}\), up to their signs, are
\begin{equation}
 h p_i(u)z_{vj},\quad h p_i(v)z_{uj},\quad
 h p_j(u)z_{iv},\quad h p_j(v)z_{iu},
\label{eq:original-30}
\end{equation}
and
\begin{equation}
 h^2p_i(s)p_j(t)z_{\bar s\bar t},
 \qquad s,t\in\{u,v\}.
\label{eq:original-31}
\end{equation}
All other coefficients have sup bounded by a fixed negative power
of \(n\). A diagonal coefficient of \(H_P\) satisfies, with its
first endpoint \(s\) fixed,
\begin{equation}
 \mathbb E_{\bar s}\bigl[|(H_P)_{ss}|^k
                  \mathbf 1_{\rm valid}\bigr]
 \le C_p n^\eta n^{-c'_0(k-2)}/l,
 \qquad 2\le k\le p,
\label{eq:original-32}
\end{equation}
where the expectation may also omit boundedly many output labels.

After expansion of a numerical update difference and of its formal
truncation tail, every term is covered by the following classes:
\begin{enumerate}
\item a term containing a non-pure swap $R$, and hence a factor $C/l$;
\item a pure-swap term with no intermediate endpoint factor;
\item a pure-swap term with exactly one endpoint $E$ factor and no
topology factor;
\item a term with a cross topology factor $b_{uv}$;
\item a pure-swap term with local topology factors only, and at
most one endpoint $E$ factor;
\item a term with at least two endpoint $E$ factors.
\end{enumerate}
In class~3 the single endpoint $E$ factor may be grouped with
$W$ outers.  For class~5, if both outers are at $u$, an opposite
local factor $j_v$ is necessary; the symmetric statement holds
for two outers at $v$.  If class~5 has no endpoint $E$ factor and
has distinct outers, local factors at both endpoints are necessary.
All remaining factors and choices of their positions can be summed
with a bounded geometric multiplier.

For every fixed entry while its labels are alive, and through
every chosen history segment, there is a fixed $c_5>0$ such that
\begin{equation}
\begin{split}
 &\sum_{\substack{t:\text{nonspecial survival}\\
                         \text{has positive probability}}}
 \frac{\bigl|\mathbb E(\Delta E_{ij}\mid
                           \text{nonspecial survival})\bigr|}{B_k}
       \leq n^{-c_5},\\
 &\sum_{\substack{t:\text{nonspecial survival}\\
                         \text{has positive probability}}}
 \frac{\mathbb E((\Delta E_{ij})^2\mid
                           \text{nonspecial survival})}{B_k^2}
       \leq n^{-c_5}.
\end{split}
\label{eq:original-39}
\end{equation}
Here $k=\nu(i)+\nu(j)$ is the pair's total level.  Each sum stops when
one of its labels dies.

Let $\Omega$ be a bounded convex domain with regular real-analytic Jordan boundary. Let $h$ be meromorphic and one-to-one on $|\lambda|>r$ including infinity, where $0<r<1$, with a simple pole at infinity as in \eqref{eq:h}, and mapping $|\lambda|>1$ onto $\C\setminus\overline\Omega$. Put $q(\lambda)=\lambda h'(\lambda)$ and define $b_k(z)$ by expansion at infinity:
\begin{equation}\label{eq:faber}
 \frac{q(\lambda)}{h(\lambda)-z}=\sum_{k\ge0}b_k(z)\lambda^{-k}.
\end{equation}
Then $b_0=1$, and each $b_k$ is a polynomial of degree $k$ with leading coefficient $c^{-k}$. There are scalars $s_{kj}$, $k,j\ge1$, such that
\begin{equation}\label{eq:boundary-basis}
 b_k(h(\mu))=\mu^k+\sum_{j\ge1}s_{kj}\mu^{-j}\quad(k\ge1).
\end{equation}
The function
\begin{equation}\label{eq:s}
 s(\lambda,\mu)=\frac{q(\lambda)}{h(\lambda)-h(\mu)}-\frac{\lambda}{\lambda-\mu}
 =\sum_{k,j\ge1}s_{kj}\lambda^{-k}\mu^{-j}
\end{equation}
extends holomorphically across the diagonal and both infinities in $|\lambda|,|\mu|>r$. For every $r<\rho<1$ there is a constant $C_\rho$ with
$|s_{kj}|\le C_\rho\rho^{k+j}$. The series converges normally on
the exterior product collar: it converges absolutely and uniformly on
every compact subset, including subsets meeting either infinity.
In particular it converges absolutely and uniformly on $\T^2$. The continuous kernel
\[
 K(\lambda,\mu)=1+s(\lambda,\mu)+\overline{s(\lambda,\mu)}
\]
is nonnegative and has integral one in each variable with the other fixed.

For every positive integer $m$ and every $M_m(\C)$-valued polynomial $G(z)=\sum_{k=0}^N b_k(z)C_k$,
\begin{equation}\label{eq:coefficient-estimate}
 \sum_{k=0}^N\HS{C_k}^2
 \le\int_\T\HS{G(h(\mu))}^2\,d\tau(\mu)
 \le\HS{C_0}^2+2\sum_{k=1}^N\HS{C_k}^2.
\end{equation}

For the fixed minimizing metric, the representation
\eqref{eq:representation-target} holds, before any bound on $\kappa$ is
proved, with
\begin{align}
 \Phi_D(\zeta)&=(I-D/\zeta)^{-1}+[(I-D/\zeta)^{-1}]^*-I,
                                                        \label{eq:phi}\\
 j(t)&=\frac{tG'(t)f'(G(t))}{\psi(t)}>0,
 &\Lambda(t)&=j(t)\Phi_D(\psi(t)).                      \label{eq:lambda}
\end{align}

There are absolute constants $c>0$ and $z_0$ with the following property.
For every real $z\ge z_0$ and every choice of a residue class
$a_p\pmod p$ for each prime $p\le z$,
\begin{equation}\label{eq:main-survivors}
 \#\{1\le n\le Y:n\not\equiv a_p\pmod p\text{ for every }p\le z\}
 \ge c\frac{YV_0}{B^2}.
\end{equation}

The functions \(a,c\) are positive and satisfy, with absolute comparison
constants,
\begin{align}
 a(s)+c(s)&=c_0(s),&
 a(s)&\asymp c_0(s),&
 c(s)&\asymp c_0(s)\qquad(s\ge1),\label{eq:functions-deficits}\\
 s a(s)&=\int_{s-1}^{\infty}c(t)\,dt
       &&(s\ge2),\label{eq:functions-future-a}\\
 s c(s)&=\int_{s-1}^{\infty}a(t)\,dt
       &&(s\ge1).\label{eq:functions-future-c}
\end{align}
For \(u\ge2\),
\begin{equation}\label{eq:functions-dickman-ratio}
 \frac1{4u^2}\le\frac{\rho(u)}{\rho(u-1)}\le\frac1u .
\end{equation}
Moreover, for each fixed \(\lambda>0\), there is \(U_\lambda\) such that
\begin{equation}\label{eq:functions-dickman-logderivative}
 -\frac{\rho'(u)}{\rho(u)}\ge\lambda\qquad(u\ge U_\lambda).
\end{equation}

For every fixed \(h>0\) there is \(C_h<\infty\) with the following
properties.  For any nonnegative measurable state function \(Q\)
and any \(v\in\R\), a regenerating start satisfies
\begin{equation}\label{eq:functions-band-from-regeneration}
 \E\sum_{n\ge1}Q(i_n,s_n)
        \1_{\{T_n\in[v,v+h]\}}
 \le C_h\sum_i\int Q(i,s)\pi_i(s)\,ds.
\end{equation}
From an even start in \eqref{eq:functions-start-range}, the same
bound holds for the sum over \(n\ge2\), uniformly in the starting
ratio.  The density of the first odd state is at most
\[
 C\,\1_{\{s\ge0.98\}}\phi_\oo(s).
\]
In particular, uniformly in \(r_{\rm in}>0\), \(R>0\), and
\(\ell\in\{1,2\}\),
\begin{equation}\label{eq:functions-inverse-phi-band}
 \E\sum_{n\ge1}
 \frac{\1_{\{R\le r_n\le eR,\ s_n<r_n/\ell\}}}
      {\phi_{i_n}(s_n)}
 \ll R+1.
\end{equation}
Including the starting state in the last sum changes its bound
by at most an absolute constant.

For the killed chain of Proposition~\ref{prop:prime-coupling}, the
probability of a nonexit bin with left endpoint $t$ at step $2\leq n\leq N$
is bounded, with an absolute constant, by
\begin{equation}\label{eq:prime-marginals}
 \begin{cases}
  C h\phi_\ee(t),&n\ \hbox{even},\\[2mm]
  C h\phi_\oo(t)\bigl(1-t^{-2}+3hW_0(t)\bigr),&n\ \hbox{odd}.
 \end{cases}
\end{equation}
At step $1$ the bound is $C hW_0(t)\phi_\oo(t)$, on the slightly
extended range $t\geq0.98$.  The constants are uniform in the starting
ratios and in $w$ sufficiently large.

Along the standard prime paths with $x>2$ from the root,
\begin{equation}\label{eq:ref-residual-sum}
 \sum_{\mathfrak p}h(\mathfrak p)
       \left|R_{i(\mathfrak p)}^{(w)}
                   (r(\mathfrak p),b(\mathfrak p))\right|=o(B^{-2}).
\end{equation}
The same assertion is uniform for lower starting ratios in
$[1.99,2.3]$ and starting cutoffs $B$ tending to infinity with the
parameters of \eqref{eq:parameters}.

At the root of the reference tree,
\begin{equation}\label{eq:ref-margin}
 \frac{B^2P_\ee(r_0,B)}{e^\gamma}
       \longrightarrow -a_\star+\frac{2I}{M_g}>0.02.
\end{equation}
In particular, there is an absolute $c_L>0$ such that
$B^2P_\ee(r_0,B)\geq c_L$ for all sufficiently large $z$.

For the continuous reference polynomial,
\begin{equation}\label{eq:ref-local-cont}
 Q_\ee(r,b)=\frac{f(r/b)}b+O(b^{-2})
 \qquad\left(b\longrightarrow\infty,\quad2\leq r/b\leq2.22\right),
\end{equation}
uniformly in the displayed ratios.  On every fixed cutoff window
$[b_0,b_1]$ with $b_0$ sufficiently large, the corresponding discrete
estimate is
\begin{equation}\label{eq:ref-local-prime}
 \frac{P_\ee(r,b)}{V(b)}
        =f(r/b)+O(1/b)+o_{w\to\infty}(1),
 \qquad b\in[b_0,b_1],\quad2\leq r/b\leq2.22.
\end{equation}
The constant in $O(1/b)$ is absolute, the last convergence is uniform
on the fixed window, and either prime endpoint convention is allowed.

Fix the parameters in \eqref{eq:inverse-box-ranges}--%
\eqref{eq:inverse-q-range}, the witnessing threshold \(\delta>0\), and
\(0<\sigma<1\).
There are constants \(c_p>0\), a list-size bound \(F<\infty\), and
\(\xi_{\rm inv}>0\), independent of the eventual choice of fixed
\(0<\xi\le\xi_{\rm inv}\), with the following property for all
sufficiently large \(z\).

The full candidate box has a list \(\mathcal A\) of at most \(F\)
reduced rationals \(A/D\) satisfying
\begin{equation}
 D\le R\mathcal Z^{10},\qquad
 |A|\le S_qR\mathcal Z^{10},\qquad
 \#\{p\in\mathcal P:p\text{ aligns with }A/D\}\ge c_p n_p .
 \label{eq:inverse-list}
\end{equation}
Outside a set of normalized harmonic box measure at most \(\sigma\),
every occurrence of
\begin{equation}
 \left|N_{pqu}-\frac{N_{pq}}u\right|
       >\delta\,\frac{YV_0}{pqu}
 \label{eq:inverse-bad-edge}
\end{equation}
has a rational \(A/D\in\mathcal A\) for which
\begin{equation}
 p\text{ aligns with }A/D,
 \qquad D q_E(A/D)\le R\mathcal Z^{10}.
 \label{eq:inverse-structure}
\end{equation}
The exceptional measure is relative to the whole box, rather than to
the subset on which \eqref{eq:inverse-bad-edge} holds.

Uniformly over all subsets $E$ of the primes less than $P$,
\begin{equation}\label{eq:stops-euler-lower}
 \sum_{\substack{d_0\le P^{.95}\\t\mid d_0\Rightarrow t\in E}}
       \frac{W_E(d_0)}{d_0}
 \ge e^{-\gamma}(.94-o(1)).
\end{equation}

Let $H,T_0,T_1$ be positive integers such that $H\ge2$, $T_0$ is
squarefree, every prime divisor of $T_0$ divides $H$, and
$(T_1,HT_0)=1$.  Put $N=HT_0$.  Let $C_0\in\Z$ satisfy $(C_0,H)=1$,
and prescribe the residue pattern
\begin{equation}
\label{eq:hyperbola-pattern}
 p_0\in(\Z/T_0\Z)^\times,\qquad k_0\in\Z/T_0\Z,\qquad
 p_1\in(\Z/T_1\Z)^\times,\qquad m_1\in\Z/T_1\Z.
\end{equation}
The residue classes modulo $1$ have their usual unique interpretation.
Let $I,J$ be bounded real intervals of lengths $X,Y_2\ge0$, with either
endpoint independently included or excluded.  For a positive integer
$l$ with $(l,HT_1)=1$, let $C_l$ be the number of integer pairs $(p,m)$
satisfying
\begin{equation}
\label{eq:hyperbola-counted-set}
\begin{gathered}
 p\in I,\qquad m\in J,\qquad l\mid p,\\
 p\equiv p_0\pmod{T_0},\qquad
 p\equiv p_1\pmod{T_1},\qquad
 m\equiv m_1\pmod{T_1},\\
 pm\equiv C_0+Hk_0\pmod N.
\end{gathered}
\end{equation}
Here $p$ is an integer variable, without a primality condition.
Uniformly in all these data,
\begin{equation}
\label{eq:hyperbola-explicit-count}
 C_l=
 \frac{XY_2\varphi(N)}{lT_1^2N^2\varphi(T_0)}
 +O\left(
 \tau(N)^2\log^2(2N)\sqrt{NT_0}
 \left(1+\frac{X}{lN}+\frac{Y_2}{N}\right)
 \right),
\end{equation}
with an absolute implied constant.

In particular, suppose that $R\to\infty$ and the data range uniformly
over families satisfying
\begin{equation}
\label{eq:hyperbola-application-range}
 R^{4/5}<H\le R\mathcal Z^{11},\qquad
 X\ll R,\qquad Y_2\le3H,\qquad
 \mathcal Z,T_0,T_1=R^{o(1)}.
\end{equation}
Then, uniformly over all the patterns and intervals above and all
squarefree $l\le R^{1/10}$ with $(l,HT_1)=1$,
\begin{equation}
\label{eq:hyperbola-application-count}
 C_l=
 \frac{XY_2\varphi(N)}{lT_1^2N^2\varphi(T_0)}
 +O\bigl(R^{3/5+o(1)}\bigr).
\end{equation}
Thus the same assertion holds with error $O(R^{7/10+o(1)})$.
Uniformity in the last two assertions means that the upper bounds
represented by $R^{o(1)}$ in
\eqref{eq:hyperbola-application-range} hold uniformly over the family;
equivalently, for every $\delta>0$ the error in
\eqref{eq:hyperbola-application-count} is $O_\delta(R^{3/5+\delta})$
for sufficiently large $R$ in that family.  No lower bound for $X/l$
is required.

