For every $0<\delta<1/20$, there are vectors
$X_N=(X_{N,0},\ldots,X_{N,N-1})\in[-1,1]^N$, one for each integer
$N\ge1$, such that
\begin{align}
 \limsup_{N\to\infty}\frac{\norm{Q_{X_N}}_\infty}{\sqrt N}
 &\le K_\delta,
 &K_\delta&=\sqrt{\frac{(1+\delta)^3}{1-\delta}},
 \label{eq:almost-maximum}\\
 \liminf_{N\to\infty}\frac1N\sum_{k=0}^{N-1}X_{N,k}^2
 &\ge1-7\delta.\label{eq:almost-energy}
\end{align}

For every $0<\delta<1/20$, there exist integers $m\ge1$ and $r\ge2$,
nonzero vectors $a_1,\ldots,a_r\in\Z^m$, a real-valued trigonometric
polynomial $F$ on $\T^m$, and a vector $v\in\R^m$ with the following
properties.  No two of the vectors $a_i$ are parallel, and
\[
 \mathcal A=\{a_1,-a_1,\ldots,a_r,-a_r\}
\]
is a containing Fourier support of $F$.  Moreover,
\begin{equation}
 \label{eq:auxiliary-norms}
 \norm{F}_\infty\le1,
 \qquad \norm{F}_2\ge1-3\delta.
\end{equation}
Writing $\lambda_a=a\cdot v$ for $a\in\mathcal A$, we have
\begin{equation}
 \label{eq:auxiliary-widths}
 \lambda_a\ne0,
 \qquad \sum_{a\in\mathcal A}|\lambda_a|<1,
 \qquad
 \frac{|\widehat F(a)|}{\sqrt{|\lambda_a|}}
 \le K_\delta,
 \qquad
 K_\delta=\sqrt{\frac{(1+\delta)^3}{1-\delta}}.
\end{equation}
All these objects depend on $\delta$ alone.

Let $g\in C_c^\infty(\R)$ and let $\beta\in\R\setminus\{0\}$ be fixed.
As $T\to\infty$ through positive real values,
\begin{equation}
 \label{eq:uniform-quadratic}
 \begin{split}
 \int_{\R}g(x)\e(T\beta x^2/2-ux)\,dx
 ={}&\frac{\e(\operatorname{sgn}(\beta)/8-u^2/(2T\beta))}
 {\sqrt{T|\beta|}}\\
 &\qquad\cdot\left(g\left(\frac{u}{T\beta}\right)
       +O_{g,\beta}(T^{-1})\right),
 \end{split}
\end{equation}
uniformly for every real $u$.

For every $0<\delta<1/20$, there exist integers $m\ge1$ and $r\ge2$,
nonzero vectors $a_1,\ldots,a_r\in\Z^m$, a real-valued trigonometric
polynomial $F$ on $\T^m$, and a vector $v\in\R^m$ with the following
properties.  No two of the vectors $a_i$ are parallel, and
\[
 \mathcal A=\{a_1,-a_1,\ldots,a_r,-a_r\}
\]
is a containing Fourier support of $F$.  Moreover,
\begin{equation}
 \label{eq:auxiliary-norms}
 \norm{F}_\infty\le1,
 \qquad \norm{F}_2\ge1-3\delta.
\end{equation}
Writing $\lambda_a=a\cdot v$ for $a\in\mathcal A$, we have
\begin{equation}
 \label{eq:auxiliary-widths}
 \lambda_a\ne0,
 \qquad \sum_{a\in\mathcal A}|\lambda_a|<1,
 \qquad
 \frac{|\widehat F(a)|}{\sqrt{|\lambda_a|}}
 \le K_\delta,
 \qquad
 K_\delta=\sqrt{\frac{(1+\delta)^3}{1-\delta}}.
\end{equation}
All these objects depend on $\delta$ alone.

Let $g\in C_c^\infty(\R)$ and let $\beta\in\R\setminus\{0\}$ be fixed.
As $T\to\infty$ through positive real values,
\begin{equation}
 \label{eq:uniform-quadratic}
 \begin{split}
 \int_{\R}g(x)\e(T\beta x^2/2-ux)\,dx
 ={}&\frac{\e(\operatorname{sgn}(\beta)/8-u^2/(2T\beta))}
 {\sqrt{T|\beta|}}\\
 &\qquad\cdot\left(g\left(\frac{u}{T\beta}\right)
       +O_{g,\beta}(T^{-1})\right),
 \end{split}
\end{equation}
uniformly for every real $u$.

Let $g\in C_c^\infty(\R)$ and $\beta\in\R\setminus\{0\}$. As
$T\to\infty$, uniformly for all $u\in\R$,
\begin{equation}\label{eq:quadratic-formula}
 \int_\R g(y)\e(T\beta y^2/2-uy)\,dy
 =\frac{\e(\sgn(\beta)/8-u^2/(2T\beta))}{\sqrt{T|\beta|}}
   \left[g\left(\frac{u}{T\beta}\right)+O_{g,\beta}(T^{-1})\right].
\end{equation}

Let $I$ be a compact interval, let $\phi$ be smooth on a neighborhood
of $I$ with $\phi''$ nowhere zero there, and let
$f\in C_c^\infty(\operatorname{int}I)$. Uniformly for $x\in[0,1]$,
\begin{equation}\label{eq:stationary-phase}
 \sqrt N\int_I f(t)\e\bigl(N(\phi(t)-xt)\bigr)\,dt
 =\frac{f(t_x)}{\sqrt{|\phi''(t_x)|}}
   \e\bigl(N(\phi(t_x)-xt_x)+\sgn(\phi'')/8\bigr)+o(1),
\end{equation}
where $t_x$ is the unique point with $\phi'(t_x)=x$ if it exists in
$I$, and the right-hand main term is zero otherwise.

Let $I$ be a compact interval, $f\in C^1(I)$, and $\phi$ be real and smooth.
If $\phi''=\Lambda\ne0$ on $I$, then for all real $k$,
\begin{equation}\label{eq:quadratic-bound}
 \left|\int_I f(t)\e(N\phi(t)-kt)\,dt\right|
 \le\frac{C}{\sqrt{N|\Lambda|}}
       \left(\norm f_\infty+\int_I|f'(t)|\,dt\right).
\end{equation}
If $N\phi'-k$ is monotone and has absolute value at least $N\rho>0$,
the same bound holds with $C/(N\rho)$ in place of
$C/\sqrt{N|\Lambda|}$.

