properties.statement_tex:
For every finite $n\ge0$, every $u:\Omega_n\to[-1,1]$, and
$-1\le\rho\le1$,
\begin{equation}
 I(T_\rho u)
 \le\psi\!\left(|\rho|\,\psi^{-1}(I(u))\right).
 \label{main:interpolation}
\end{equation}
The inverse is the nonnegative increasing branch on $[0,L]$.
For $n\ge1$, every soft coordinate $u(x)=a x_i$, $|a|\le1$,
attains equality.

For every finite $n\ge0$, $\rho\in[-1,1]$, and
$f:\Omega_n\to\{-1,1\}$, put
$m=\E f$ and $r_m=\psi^{-1}(H(m))$.  Then
\begin{equation}
 I(f(X);Y)\le\psi(|\rho|r_m)\le\psi(|\rho|).
 \label{main:bound}
\end{equation}
For $n\ge1$, signed coordinate functions attain the bound at $m=0$.
If $0<|m|<1$ and $0<|\rho|\le1$, the refined upper curve is
strictly below the universal curve $\psi(|\rho|)$.

For every finite $n\ge0$ and every $g:\{-1,1\}^n\to(-1,1)$,
with $m=\E g$,
\begin{equation}
 D(g)\ge\widehat{\mathcal B}_m(I(g))
       =\max\{\mathcal B_m(I(g)),F(I(g))\}
       \ge F(I(g)).
 \label{upgrade:production-bound}
\end{equation}

For $-1<m<1$ and $0\le\delta<1-|m|$, put
\[
 A=1-m,\qquad
 \kappa=\frac12\log\frac1{1-\delta^2/(1+m)^2}.
\]
Then
\begin{equation}
 A^2\log\frac\alpha\beta\le3\kappa.
 \label{reserve:log-geometry}
\end{equation}

For every physical state $(m,\delta,e)$ and $0<\tau\le1$,
\begin{equation}
 W(1-\tau+\tau m,\tau\delta,\tau e)
 \le\tau W(m,\delta,e).
 \label{reserve:plus-corner}
\end{equation}
The same inequality holds with parent mean $-1+\tau+\tau m$,
corresponding to the negative common output.  There is no sign
restriction on the original mean.

For $|r|\le1$,
\begin{equation}
\label{scalar:entropy-quadratic-bounds}
 \frac{r^2}{2}\le\psi(r)\le Lr^2,\qquad H(r)\ge L(1-r^2).
\end{equation}
The quotient $\psi(r)/r^2$ is strictly increasing for $0<r<1$.
Moreover,
\begin{equation}
\label{scalar:logarithm-constants}
 \frac23<L<\frac{25}{36}<\frac7{10},\qquad
 \frac12<M:=\frac{4L^2}{3}<\frac23.
\end{equation}

The function $F$ is smooth on $[0,L)$, with right derivatives at zero,
and
\begin{equation}
\label{scalar:production-convexity}
 F(0)=0,\qquad F'(0)=2,\qquad F''(0)=\frac43,\qquad
 F''(I)\ge\frac43,\qquad F'''(I)\ge0.
\end{equation}
The zero-extended surplus $S$ is nonnegative, nondecreasing, convex, and
$C^1$ on $(-\infty,L)$, with $S(0)=S'(0)=0$.  It is not $C^2$ at zero.

For $0<h\le L$, put
\begin{equation}
\label{scalar:scaled-curvature-definition}
 P(h)=h^2F''(L-h).
\end{equation}
Then
\begin{equation}
\label{scalar:scaled-curvature-range}
 \frac12\le P(h)\le M=\frac{4L^2}{3},\qquad P(L)=M.
\end{equation}

For the core and mass in \eqref{thinning:path},
\begin{equation}
\label{thinning:value}
 F(\nu+J)-F(\nu)\le\lambda F(J_c).
\end{equation}

Every state on \eqref{thinning:path} satisfies
\begin{equation}
\label{thinning:window-bound}
 \int_q^s\frac{(h-b)_+}{h^2}\,dh\le3\kappa.
\end{equation}

For $|m|<1$ and $L/2\le I<H(m)$,
\begin{equation}
 \mathcal B_m(I)\ge F(I).
 \label{upgrade:high-information-bound}
\end{equation}
The inequality is strict if $m\ne0$. Consequently a state with
$F(I)>\mathcal B_m(I)$ must have $I<L/2$.

For every \(n\ge1\), every Boolean function
\(f:\{-1,1\}^n\to\{-1,1\}\), and every \(\rho\in[-1,1]\), writing \(m=\E f\), one has
\begin{equation}\label{eq:main}
H(m)-\E H(T_\rho f)\le1-H(\rho).
\end{equation}
Both expectations are with respect to the uniform probability measure.

Let $f$ be a nonconstant Boolean function, let $0<\rho<1$, and suppose that
$s\ge .84$ and $0\le m\le r^2/2$.  If
\begin{equation}\label{cen:crossing}
 b=h-1+s,\qquad \mathcal E(d)\le K=\frac rs,
\end{equation}
then $f$ is a signed coordinate.

At a crossing in the central band,
\begin{equation}\label{cen:four-constants}
 \frac{\Phi(M)}M<.0063,\qquad p_*<.019,\qquad
 \frac{p_*}M<.0532,\qquad \frac\Delta M<.008.
\end{equation}

Under the central-band crossing hypotheses of Proposition~\ref{prop:central},
for every $0\le u\le1$,
\begin{equation}\label{cen:pointwise-bound}
 D(u)-2\alpha m|R|+.88m^2
 \ge C_0(g^2-M)^2+.20(u^2-y^2)^2.
\end{equation}
The inequality is strict whenever $u\ne y$.

Inequality \eqref{cen:variance-gain} holds.  If $m>0$, the stronger bound
\begin{equation}\label{cen:positive-margin}
 \Var g-M>C_0V_0-\frac\Delta{1+p_*}+.016m^2
\end{equation}
holds.  If $m=0$, \eqref{cen:variance-gain} is strict unless $g^2=M$
at every point of the cube.

With the preceding notation,
\begin{equation}\label{eq:basic-energy}
\mathcal E(d)\ge\sum_i\E(D_i g)^2\ge\Var(g).
\end{equation}

Set
\[
p=\frac{1-m}{2},\qquad
w=\min\left\{2p,\;4\sqrt{\frac32}\,p^{3/2}\right\}.
\]
Then
\begin{align}
W_1(f)&\le w,\label{eq:first-level-bound}\\
\Var(d)&\le r[(1-r)w+rh^2].\label{eq:variance-bound}
\end{align}
If \(d_{\rm o}(x)=(d(x)-d(-x))/2\) is the odd part of \(d\), then
\begin{equation}\label{eq:odd-variance-bound}
\E d_{\rm o}^2\le r[(1-r^2)w+r^2h^2].
\end{equation}

For the fixed $s$, parameters, and profile above, every increasing
Boolean function satisfies
\begin{equation}\label{ind:eq:all-dimensions}
 \E G\bigl((1+T_\rho f)/2\bigr)\ge sB(\E f).
\end{equation}

For every \(-1<d<1\), with \(V,\Psi\) defined by
\eqref{mid:V} and \eqref{mid:Psi}, one has
\begin{equation}\label{mid:pointwise-bounds}
 \begin{array}{ll}
 \Psi\ge(\frac12-2m^2)V^2,&0\le m\le\frac15,\\[2pt]
 \Psi\ge-\frac1{100}V,&\frac15\le m\le\frac23,\\[2pt]
 \Psi\ge-\frac1{50}V,&\frac23\le m\le\frac{37}{50}.
 \end{array}
\end{equation}

For every positive function $a$ on the uniform cube,
\begin{equation}\label{lb:entropy-bound}
 \operatorname{Ent}(a^2)\le2\E a\mathcal Na.
\end{equation}

Let $u_0\ge0$ be a real function on the cube, $\tau\ge0$, and
$r=e^{-2\tau}$. For every $q>0$, $q\ne1$, put
$p_q=1+r(q-1)$. Then
\begin{equation}\label{lb:norm-moments}
 \E(T_{e^{-\tau}}u_0)^q
 \begin{cases}
 \displaystyle\le(\E u_0^{p_q})^{q/p_q},&q>1,\\[2pt]
 \displaystyle\ge(\E u_0^{p_q})^{q/p_q},&0<q<1.
 \end{cases}
\end{equation}

